  ui_story_31800401_122_dialog_content = "Vice dan aku adalah kawan yang telah selamat dari situasi hidup dan mati bersama di medan perang. Kami bekerja dan membuat keputusan bersama hampir setiap hari.",
  ui_story_31800401_123_dialog_content = "Itu sebabnya dia sering datang ke Colossus—untuk membantuku mengelola tempat ini.",
  ui_story_31800401_124_dialog_content = "Carleen ada di sini hanya karena saya memintanya untuk membantu saya menemukan pemasok makanan penutup untuk kafe di Colossus.",
  ui_story_31800401_125_dialog_content = "Itu sebabnya dia membawakanku kue itu untuk dicicipi!",
  ui_story_31800401_126_dialog_content = "Adapun Lilica, kami kebetulan bertemu satu sama lain dan berbasa-basi, itu saja!",
  ui_story_31800401_127_dialog_content = "Tidak bisakah Anda melihat betapa besar masalah yang mungkin terjadi pada mereka dan saya jika Anda menerbitkan semua omong kosong itu?",
  ui_story_31800401_128_dialog_content = "Oh... Anda tahu, Anda ada benarnya juga.",
  ui_story_31800401_129_dialog_content = "Maaf, saya terlalu fokus membuat cerita ini berhasil... Saya membiarkan ambisi saya memengaruhi integritas dan visi jurnalistik saya.",
  ui_story_31800401_130_dialog_content = "Ketika saya memikirkannya dengan pikiran tenang, maka ya — ini adalah jenis gosip yang disukai tabloid untuk memberi makan massa.",
  ui_story_31800401_131_dialog_content = "Aku tidak percaya aku sesaat berubah menjadi tipe orang yang aku benci bahkan tanpa menyadarinya.",
  ui_story_31800401_132_dialog_content = "Aku sangat menyesal, PlayerName. Saya akan menghapus foto-foto ini, jangan khawatir.",
  ui_story_31800401_133_option_content = "Tidak perlu minta maaf.",
  ui_story_31800401_134_dialog_content = "J-Jangan dimasukkan ke dalam hati.",
  ui_story_31800401_135_dialog_content = "Saya tidak marah. Saya hanya khawatir pendapat publik yang berubah-ubah mungkin berdampak negatif pada orang lain.",
  ui_story_31800401_136_dialog_content = "Jika Anda dapat memikirkan ide lain untuk fitur khusus, saya akan memberikan kerja sama penuh saya.",
  ui_story_31800401_137_dialog_content = "Kau orang yang sangat baik hati.",
  ui_story_31800401_138_dialog_content = "Anda masih memikirkan kepentingan terbaik saya setelah semua yang telah saya lakukan.",
  ui_story_31800401_139_option_content = "Lebih berhati-hati saja lain kali.",
  ui_story_31800401_140_dialog_content = "Bukan masalah besar.",
  ui_story_31800401_141_dialog_content = "Saya harap Anda tidak melupakan aspirasi karier Anda dan tidak menjadi salah satu paparazzi yang tidak tahu malu.",
  ui_story_31800401_142_dialog_content = "Tetapi jika Anda dapat memikirkan cara lain untuk membantu Anda, Anda dapat mengandalkan dukungan saya.",
  ui_story_31800401_143_dialog_content = "Saya mengerti. Terima kasih, PlayerName.",
  ui_story_31800401_144_dialog_content = "Sigh, tapi jika saya tidak bisa menggunakan ini, apa yang harus saya tulis...?",
  ui_story_31800401_145_dialog_content = "Hei, tunggu!",
  ui_story_31800401_146_dialog_content = "Apa?",
  ui_story_31800401_147_dialog_content = "\"Berita terbaru! Caelestite muda yang tampan masih lajang! Serang selagi setrika masih panas!\"",
  ui_story_31800401_148_dialog_content = "Dengan cerita seperti ini, kita bisa tetap berpegang pada fakta dan memberikan apa yang diinginkan penonton!",
  ui_story_31800401_149_dialog_content = "Hah? Tunggu sebentar sekarang—",
  ui_story_31800401_150_dialog_content = "Itu sempurna! Ini pasti akan menjadi headline besar berikutnya!",
  ui_story_31800401_151_dialog_content = "Saya akan kembali dan menulis artikel saya sekarang. Terima kasih, PlayerName!",
